#include "stdafx.h"#include "ServerExPlugin_Model.h"#include <enumquerytypes.h>#include <CommonRSUs.h>#include <macros/AutoCloser.h>#include <serverexplugintypes.h>#include <Model2OperatorMessages.h>extern "C" SERVEREXPLUGIN_MODEL_API DWORD MessagesSupport( BYTE **buffer, int &sizeReq, DWORD rsuID, tMemReallocer pMemR ){  DWORD size = 0;  if( id_Model != rsuID )    return size;  BYTE *pRequest = *buffer;  QueryTypes qType = *(QueryTypes*) pRequest;  int* N = (int*)(pRequest + sizeof(QueryTypes));  FILETIME fileCreation,fileLastWrite;  KAutoCloser<HANDLE> hHandle( ::CreateFile( GetModel2OperatorMessagesFilePath(),                                            GENERIC_READ|GENERIC_WRITE,                                            FILE_SHARE_READ|FILE_SHARE_WRITE,                                            NULL,                                            OPEN_ALWAYS,                                            FILE_ATTRIBUTE_NORMAL,                                            NULL ),                               ::CloseHandle );  if ( hHandle != INVALID_HANDLE_VALUE)   {    if( !GetFileTime(hHandle, &fileCreation, NULL, &fileLastWrite) )      return size;  }  //  OVERLAPPED Overlapped = {0,0,N[0]*sizeof(CModel2OperatorMessages),0,0};  DWORD nReadBytes      =      N[1]*sizeof(CModel2OperatorMessages);  DWORD nBytesRead;  // Используем в качестве выходного буфера - входной  *buffer = pMemR( *buffer, nReadBytes, sizeReq );  BOOL bResult = ReadFile( hHandle, *buffer, nReadBytes, &nBytesRead, &Overlapped );  if ( bResult && nReadBytes == nBytesRead )    return nBytesRead;  return size;}